A Mapping is a dictionary where <ul> <li>the keys are virtual qubit indices (from 0 to virtual_qubit_register_size-1), and</li> <li>the values are physical qubit indices.</li> </ul> <p>Parameters:</p> Name Type Description Default <code>physical_qubit_register</code> <code>list[int]</code> <p>a list of physical qubit indices.</p> required <p>Raises:</p> Type Description <code>ValueError</code> <p>If the mapping is incorrect.</p> Source code in <code>opensquirrel/passes/mapper/mapping.py</code> <pre><code>class Mapping:
    """A Mapping is a dictionary where:
       - the keys are virtual qubit indices (from 0 to virtual_qubit_register_size-1), and
       - the values are physical qubit indices.

    Args:
        physical_qubit_register: a list of physical qubit indices.

    Raises:
        ValueError: If the mapping is incorrect.
    """

    def __init__(self, physical_qubit_register: list[int]) -&gt; None:
        self.data: dict[int, int] = dict(enumerate(physical_qubit_register))
        if (self.data.keys()) != set(self.data.values()):
            msg = f"the mapping {self!r} is incorrect"
            raise ValueError(msg)

    def __eq__(self, other: Any) -&gt; bool:
        if not isinstance(other, Mapping):
            return False

        if len(self.data) != len(other.data):
            return False

        if set(self.data.keys()) != set(other.data.keys()):
            return False

        return all(self.data[key] == other.data[key] for key in self.data)

    def __getitem__(self, key: int) -&gt; int:
        return self.data[key]

    def __len__(self) -&gt; int:
        return len(self.data)

    def __repr__(self) -&gt; str:
        return f"Mapping({self.data!r})"

    def size(self) -&gt; int:
        return len(self.data)

    def items(self) -&gt; list[tuple[int, int]]:
        return list(self.data.items())

    def keys(self) -&gt; list[int]:
        return list(self.data.keys())

    def values(self) -&gt; list[int]:
        return list(self.data.values())
